}

PROFILE_ALIASES = {
    "generic": "generic",
    "none": "generic",
    "c4": "c4-review",
    "c4 review": "c4-review",
    "c4 review canvas": "c4-review",
    "architecture review board": "c4-review",
    "c4 评审画布": "c4-review",
    "架构评审画布": "c4-review",
    "c4-review": "c4-review",
    "cloud": "cloud-fabric",
    "cloud deployment": "cloud-fabric",
    "deployment topology": "cloud-fabric",
    "multi region deployment map": "cloud-fabric",
    "云部署拓扑": "cloud-fabric",
    "多区域部署图": "cloud-fabric",
